/*
 * A257911  Sequence (a(n)) generated by Algorithm (in Comments) with a(1) = 2
 *          and d(1) = 2.
 * https://oeis.org/A257911
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 183, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Algorithmic construction of OEIS sequence A257911.
   a(1) = 2, d(1) = 2.
   For k ≥ 1:
      let h be the least integer > -a(k) such that
           h ∉ D(k)  and  a(k)+h ∉ A(k).
      then a(k+1) = a(k)+h,  d(k+1) = h.
   The function returns a(n) for any n ≥ 1.  Indices are 1‑based
   as in the OEIS entry. */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ensure that a memory block has at least `need` elements */
static void ensure_capacity_seq(void **ptr, size_t *cap, size_t need, size_t elem_size)
{
    if (*cap < need)
    {
        size_t new_cap = (*cap > 0) ? (*cap * 2) : 4;
        if (new_cap < need) new_cap = need;
        *ptr = realloc(*ptr, new_cap * elem_size);
        *cap = new_cap;
    }
}

seq_t a(idx_t n)
{
    /* static data kept between calls */
    static seq_t *a_vals = NULL;      /* a(1),a(2),… */
    static size_t a_cap = 0, a_len = 0;
    static long long *d_vals = NULL;   /* d(1),d(2),… */
    static size_t d_cap = 0, d_len = 0;

    /* initialise with first term */
    if (a_len == 0)
    {
        ensure_capacity_seq((void **)&a_vals, &a_cap, 1, sizeof(seq_t));
        a_vals[0] = (seq_t)2;      /* a(1) = 2 */
        a_len = 1;

        ensure_capacity_seq((void **)&d_vals, &d_cap, 1, sizeof(long long));
        d_vals[0] = 2;             /* d(1) = 2 */
        d_len = 1;
    }

    /* compute missing terms up to n */
    while (a_len < (size_t)n)
    {
        seq_t a_k = a_vals[a_len - 1];

        /* smallest integer strictly greater than -a_k */
        long long h = -(long long)a_k + 1;

        /* search for a suitable h */
        while (1)
        {
            /* reject h already used as a difference */
            bool h_used = false;
            for (size_t i = 0; i < d_len; ++i)
                if (d_vals[i] == h) { h_used = true; break; }
            if (h_used) { ++h; continue; }

            /* compute candidate new_a = a_k + h */
            seq_t new_a;
            if (h >= 0)
                new_a = a_k + (seq_t)h;
            else
                new_a = a_k - (seq_t)(-h);   /* a_k ≥ -h + 1, so no underflow */

            /* reject if new_a already seen */
            bool a_used = false;
            for (size_t i = 0; i < a_len; ++i)
                if (a_vals[i] == new_a) { a_used = true; break; }
            if (a_used) { ++h; continue; }

            /* acceptable h found */
            ensure_capacity_seq((void **)&a_vals, &a_cap, a_len + 1, sizeof(seq_t));
            ensure_capacity_seq((void **)&d_vals, &d_cap, d_len + 1, sizeof(long long));

            a_vals[a_len++] = new_a;
            d_vals[d_len++] = h;
            break;
        }
    }

    return a_vals[n - 1];
}
